import type { PluginHost } from '@sluice-dev/plugin-api';

/** Markdown CLI + MCP reference generated from the registered plugins (docs/reference/cli.md). */
const text = (s: string) => s.replace(/\|/g, '\\|').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, ' ');

export function renderReference(host: PluginHost): string {
  const out = [
    '# CLI & MCP reference',
    '',
    '<!-- generated by `pnpm docs:gen` from the plugin registry — do not edit -->',
    '',
    'Every command and tool below is contributed through the [plugin API](../plugin-api.md).',
    '',
  ];
  const byPlugin = new Map<string, ReturnType<PluginHost['commands']>>();
  for (const c of host.commands()) byPlugin.set(c.plugin, [...(byPlugin.get(c.plugin) ?? []), c]);
  for (const [plugin, cmds] of byPlugin) {
    out.push(`## ${plugin}`, '');
    for (const { spec } of [...cmds].sort((a, b) => a.spec.path.join(' ').localeCompare(b.spec.path.join(' ')))) {
      const args = (spec.args ?? [])
        .map((a) => (a.required ? `<${a.name}${a.variadic ? '...' : ''}>` : `[${a.name}${a.variadic ? '...' : ''}]`))
        .join(' ');
      out.push(`### \`sluice ${spec.path.join(' ')}${args ? ' ' + args : ''}\``, '', text(spec.summary), '');
      if (spec.options?.length) {
        out.push('| option | description |', '|---|---|');
        for (const o of spec.options)
          out.push(
            `| \`${o.flags}\` | ${text(o.description)}${o.required ? ' (required)' : ''}${o.default !== undefined ? ` (default: \`${String(o.default)}\`)` : ''} |`,
          );
        out.push('');
      }
    }
  }
  out.push(
    '## MCP tools',
    '',
    'Served by `sluice-mcp` (stdio). Human-only actions (approving scenarios, step-up approvals, answering decisions) are intentionally not tools.',
    '',
    '| tool | plugin | description |',
    '|---|---|---|',
  );
  for (const { plugin, spec } of [...host.tools()].sort((a, b) => a.spec.name.localeCompare(b.spec.name))) {
    out.push(`| \`${spec.name}\` | ${plugin} | ${text(spec.description)} |`);
  }
  return out.join('\n') + '\n';
}
